$Title         = 'Claude Code'        # 팝업 제목
$Message       = '생각 끝~!'    # 팝업 내용
$ShowMs        = 5000                 # 표시 시간(밀리초) → 이후 자동 닫힘
$TargetMonitor = '1/2'          # 팝업 띄울 모니터: 'secondary'(주모니터 아닌 화면) / 'primary' / 1,2,3..(번호)

# 소리: 아래 한 줄을 원하는 것으로 바꾸세요.
#   시스템 사운드: Asterisk(기본) / Beep / Exclamation / Hand / Question
$PlaySound = { [System.Media.SystemSounds]::Hand.Play() }
- $PlaySound = { $f=Get-Random @('tada','chimes','notify','Ring03','Windows Print
#   ▶ 직접 멜로디:  $PlaySound = { [console]::beep(880,150); [console]::beep(1175,220) }
#   ▶ 내 wav 파일:  $PlaySound = { (New-Object System.Media.SoundPlayer 'C:\Users\Lenovo\.claude\ding.wav').PlaySync() }
# ────────────────────────────────────────────────────────────────────

# 1) 소리
try { & $PlaySound } catch {}

# 2) 독립 팝업 창 (Windows 알림 설정과 무관하게 항상 표시, 지정 모니터 우측 하단)
try {
  Add-Type -AssemblyName System.Windows.Forms
  Add-Type -AssemblyName System.Drawing

  # 포커스를 빼앗지 않는 창(타이핑 방해 X). 컴파일 실패 시 일반 창으로 폴백.
  try {
    Add-Type -ReferencedAssemblies System.Windows.Forms -TypeDefinition @"
using System;
using System.Windows.Forms;
public class NoActivateForm : Form {
  protected override bool ShowWithoutActivation { get { return true; } }
  protected override CreateParams CreateParams {
    get { CreateParams cp = base.CreateParams; cp.ExStyle |= 0x08000000; return cp; } // WS_EX_NOACTIVATE
  }
}
"@ -ErrorAction Stop -WarningAction SilentlyContinue
    $form = New-Object NoActivateForm
  } catch {
    $form = New-Object System.Windows.Forms.Form
  }

  # 대상 모니터 선택
  $screens = [System.Windows.Forms.Screen]::AllScreens
  switch ("$TargetMonitor") {
    'primary'   { $target = [System.Windows.Forms.Screen]::PrimaryScreen }
    'secondary' {
      $target = $screens | Where-Object { -not $_.Primary } | Select-Object -First 1
      if (-not $target) { $target = [System.Windows.Forms.Screen]::PrimaryScreen }
    }
    default {
      $idx = 0
      if ([int]::TryParse("$TargetMonitor", [ref]$idx) -and $idx -ge 1 -and $idx -le $screens.Count) {
        $target = $screens[$idx - 1]
      } else { $target = [System.Windows.Forms.Screen]::PrimaryScreen }
    }
  }
  $wa = $target.WorkingArea

  $form.FormBorderStyle = 'None'
  $form.StartPosition   = 'Manual'
  $form.TopMost         = $true
  $form.ShowInTaskbar   = $false
  $form.BackColor       = [System.Drawing.Color]::FromArgb(30,30,30)
  $form.Width  = 360
  $form.Height = 116
  $form.Left   = $wa.Right  - $form.Width  - 16
  $form.Top    = $wa.Bottom - $form.Height - 16

  $accent = New-Object System.Windows.Forms.Panel
  $accent.SetBounds(0,0,5,$form.Height)
  $accent.BackColor = [System.Drawing.Color]::FromArgb(80,160,255)
  $form.Controls.Add($accent)

  $lblT = New-Object System.Windows.Forms.Label
  $lblT.Text = $Title
  $lblT.ForeColor = [System.Drawing.Color]::White
  $lblT.Font = New-Object System.Drawing.Font('Segoe UI', 12, [System.Drawing.FontStyle]::Bold)
  $lblT.SetBounds(20,16,324,28)
  $form.Controls.Add($lblT)

  $lblM = New-Object System.Windows.Forms.Label
  $lblM.Text = $Message
  $lblM.ForeColor = [System.Drawing.Color]::Gainsboro
  $lblM.Font = New-Object System.Drawing.Font('Segoe UI', 11)
  $lblM.SetBounds(20,50,324,48)
  $form.Controls.Add($lblM)

  # 자동 닫힘 타이머 + 클릭 시 즉시 닫힘
  $timer = New-Object System.Windows.Forms.Timer
  $timer.Interval = [int]$ShowMs
  $timer.Add_Tick({ $timer.Stop(); $form.Close() })
  $form.Add_Shown({ $timer.Start() })
  $close = { $form.Close() }
  $form.Add_Click($close); $lblT.Add_Click($close); $lblM.Add_Click($close); $accent.Add_Click($close)

  [System.Windows.Forms.Application]::Run($form)
} catch {}

