import { NextResponse } from "next/server";

/**
 * 요청의 실제 접속 origin(scheme://host).
 *
 * Next dev의 `req.url`은 서버가 바인드한 호스트(localhost)로 정규화되어, LAN/IP(예:
 * http://172.16.30.47:4310)나 리버스 프록시로 들어온 요청에 대해서도 localhost를 돌려준다.
 * 그 값으로 redirect를 만들면 원격 브라우저가 자기 localhost로 튕겨 로그인이 깨진다.
 * 따라서 X-Forwarded-Host/Host 헤더로 "브라우저가 실제로 친 origin"을 복원한다.
 */
export function requestOrigin(req: Request): string {
  const host = req.headers.get("x-forwarded-host") || req.headers.get("host");
  if (!host) return new URL(req.url).origin;
  const proto =
    req.headers.get("x-forwarded-proto") ||
    (process.env.NODE_ENV === "production" ? "https" : "http");
  return `${proto}://${host}`;
}

/** requestOrigin 기준 상대경로로 리다이렉트(LAN/프록시에서도 같은 호스트 유지). */
export function redirectTo(req: Request, path: string): NextResponse {
  return NextResponse.redirect(new URL(path, requestOrigin(req)));
}

