2	import { getSessionUser } from "@/lib/auth/session";
3	import { assertScopeAllowed, scopeWikiPrefix } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { answerQuery } from "@/lib/query";
6	import { answerWithWebSearch } from "@/lib/websearch";
7	import { checkDailyBudget, recordUsage } from "@/lib/cost";
8	import { MODELS } from "@/lib/anthropic";
9	
10	// 질의 탭 ↔ 실제 LLM. 세션 + ACL(강제지점1) + 대화 세션(멀티턴) + 출처 질의(Opus). docs/07.
11	export const runtime = "nodejs";
12	export const maxDuration = 300;
13	
14	export async function POST(req: Request) {
15	  const user = await getSessionUser();
16	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
17	
18	  const { scope, question, conversationId, web } = await req.json();
19	  if (typeof scope !== "string" || typeof question !== "string" || !question.trim()) {
20	    return NextResponse.json({ error: "scope·question이 필요합니다." }, { status: 400 });
21	  }
22	
23	  // ACL 강제지점1: 질의 입력 — 허용 scope가 아니면 거부
24	  try {
