import { NextResponse } from "next/server";
import { prisma } from "@/lib/db";
import { createSession } from "@/lib/auth/session";
import { redirectTo } from "@/lib/http";

// 개발용 로컬 로그인 — agora SSO 없이 로컬/사내망(4310)에서 테스트(docs/11 §1). 프로덕션 비활성.
//
// ?as=<이름> 없음 → 기본 관리자 계정(dev:local, ADMIN) + 샘플 룸 시드. (호스트 본인용)
// ?as=<이름> 있음 → 이름별 독립 USER 계정(dev:<slug>). 같은 와이파이의 동료가 각자
//   다른 신원으로 들어와 룸 초대·ACL·개인위키를 실제 다중 사용자로 테스트하기 위함.
//   비밀번호가 없으므로 신뢰된 사내망에서만 사용(아무나 임의 이름으로 로그인 가능).
export const runtime = "nodejs";

function slugify(name: string): string {
  return name.trim().toLowerCase()
    .replace(/[^a-z0-9가-힣]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
}

export async function GET(req: Request) {
  if (process.env.NODE_ENV === "production") {
    return new NextResponse("dev login disabled in production", { status: 403 });
  }

  const asRaw = new URL(req.url).searchParams.get("as")?.trim() || "";
  const slug = slugify(asRaw);

  // ── 게스트(이름 지정): 이름별 독립 USER 계정. 샘플 룸 시드 없음(초대로만 합류). ──
  if (slug) {
    const guest = await prisma.user.upsert({
      where: { ssoSubject: `dev:${slug}` },
      update: { name: asRaw },
      create: {
        ssoSubject: `dev:${slug}`,
        email: `${slug}@dev.local`,
        name: asRaw,
        role: "USER",
        emailVerifiedAt: new Date(),
      },
    });
    await createSession(guest.id);
    return redirectTo(req, "/");
  }

  // ── 기본: 호스트 관리자 계정 + 샘플 룸 시드(사이드바 채움, idempotent) ──
  const user = await prisma.user.upsert({
    where: { ssoSubject: "dev:local" },
    update: {},
    create: {
      ssoSubject: "dev:local",
      email: "dev@bns.co.kr",
      name: "개발자(로컬)",
      role: "ADMIN",
      emailVerifiedAt: new Date(),
    },
  });
  const seed: Array<[string, string, "OWNER" | "MEMBER"]> = [
    ["alpha", "프로젝트 알파", "OWNER"],
    ["beta", "제품 베타팀", "MEMBER"],
  ];
  for (const [slug, name, role] of seed) {
    const p = await prisma.project.upsert({
      where: { slug },
      update: {},
      create: { slug, name, ownerId: user.id },
    });
    await prisma.projectMembership.upsert({
      where: { userId_projectId: { userId: user.id, projectId: p.id } },
      update: { role },
      create: { userId: user.id, projectId: p.id, role },
    });
  }

  await createSession(user.id);
  return redirectTo(req, "/");
}

