Write-Output "=== ollama CLI 설치? ==="
$o = Get-Command ollama -ErrorAction SilentlyContinue
if ($o) { $o.Source } else { "ollama 미설치 (PATH에 없음)" }
Write-Output "=== Ollama 서버 응답? (localhost:11434/api/tags) ==="
try {
  $r = Invoke-RestMethod -Uri "http://localhost:11434/api/tags" -TimeoutSec 3
  Write-Output "서버 실행 중 ✅ — 받아진(pull) 모델:"
  if ($r.models) { $r.models | ForEach-Object { "  - $($_.name)  ($([math]::Round($_.size/1GB,2)) GB)" } } else { "  (받아진 모델 없음)" }
} catch {
  Write-Output "서버 응답 없음 ❌ — Ollama가 안 떠 있거나 미설치: $($_.Exception.Message)"
}

