1	import { createHash } from "node:crypto";
2	import { promises as fs } from "node:fs";
3	import path from "node:path";
4	import { prisma } from "./db";
5	import { callStructured, MODELS, providerFor } from "./anthropic";
6	import { wikiAbsPath } from "./wiki/paths";
7	import { assertWikiReady, commitAll, withWikiWriteLock } from "./wiki/repo";
8	import { applyEditSet, type EditSet } from "./wiki/applyEditSet";
9	import { loadBrain, loadIndex, loadPages } from "./wiki/context";
10	import { recordUsage } from "./cost";
11	
12	export interface IngestInput {
13	  scope?: string; // 위키 디렉터리 경로(common/personal/<id>/project-<slug>)
14	  title: string;
15	  text: string; // md 본문(텍스트) 또는 이미지 캡션/지시
16	  type?: string; // 기본 'MD' (이미지는 'IMAGE')
17	  userId?: number | null; // 업로더(provenance)
18	  images?: { mediaType: string; dataBase64: string }[]; // 멀티모달: 첨부 이미지(비전)
19	  documents?: { mediaType: string; dataBase64: string }[]; // 첨부 문서(PDF)
20	  rawBytes?: Buffer; // 원본 스냅샷을 바이트로 저장(이미지·PDF 등). 없으면 text 저장
21	  rawExt?: string; // 원본 확장자(기본 'md')
22	  // 4h 추출 메타·자산 (docs/17)
23	  mimeType?: string;
24	  byteSize?: number;
25	  originalName?: string;
26	  extractor?: string;
27	  extractStatus?: string; // FULL|PARTIAL|NONE|UNANALYZED
28	  normalizedText?: string; // 추출 정규화본(텍스트경로) → <sha>.normalized.md 사이드카
29	  assets?: { name: string; bytes: Buffer; mediaType: string }[]; // 문서 내장 이미지(raw 보존 + 비전 첨부)
30	}
31	
32	export interface IngestResult {
33	  status: "APPLIED" | "SKIPPED_DUP" | "NEEDS_REVIEW";
34	  sourceId: number;
35	  jobId?: number;
36	  commitSha?: string;
37	  changedPaths?: string[];
38	  confidence?: number;
39	  needsHuman?: boolean;
40	}
41	
42	// submit_edit_set 도구의 입력 스키마 (docs/06 §2). Phase 1은 op를 create|append로 제한.
43	const EDIT_SET_SCHEMA: Record<string, unknown> = {
44	  type: "object",
45	  properties: {
46	    edits: {
47	      type: "array",
48	      description: "위키에 적용할 파일 편집 목록",
49	      items: {
50	        type: "object",
51	        properties: {
52	          op: { type: "string", enum: ["create", "append"] },
