391	      title: input.title,
392	      rawPath: rawRel,
393	      uploadedBy: input.userId ?? null,
394	      mimeType: input.mimeType ?? null,
395	      byteSize: input.byteSize ?? input.rawBytes.byteLength,
396	      originalName: input.originalName ?? null,
397	      extractor: "none",
398	      extractStatus: "UNANALYZED",
399	      provenance: JSON.stringify({ uploadedAt: now.toISOString(), unanalyzed: true }),
400	    },
401	  });
402	
403	  try {
404	    await withWikiWriteLock(async () => {
405	      const abs = wikiAbsPath(rawRel);
406	      await fs.mkdir(path.dirname(abs), { recursive: true });
407	      await fs.writeFile(abs, input.rawBytes);
408	      return commitAll(`store(${input.scope}): ${input.title} [미분석]`, {
409	        team: input.scope,
