import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import path from "node:path";
import { prisma } from "./db";
import { callStructured, MODELS, providerFor } from "./anthropic";
import { wikiAbsPath } from "./wiki/paths";
import { assertWikiReady, commitAll, withWikiWriteLock } from "./wiki/repo";
import { applyEditSet, type EditSet } from "./wiki/applyEditSet";
import { loadBrain, loadIndex, loadPages } from "./wiki/context";
import { recordUsage } from "./cost";

export interface IngestInput {
  scope?: string; // 위키 디렉터리 경로(common/personal/<id>/project-<slug>)
  title: string;
  text: string; // md 본문(텍스트) 또는 이미지 캡션/지시
  type?: string; // 기본 'MD' (이미지는 'IMAGE')
  userId?: number | null; // 업로더(provenance)
  images?: { mediaType: string; dataBase64: string }[]; // 멀티모달: 첨부 이미지(비전)
  documents?: { mediaType: string; dataBase64: string }[]; // 첨부 문서(PDF)
  rawBytes?: Buffer; // 원본 스냅샷을 바이트로 저장(이미지·PDF 등). 없으면 text 저장
  rawExt?: string; // 원본 확장자(기본 'md')
  // 4h 추출 메타·자산 (docs/17)
  mimeType?: string;
  byteSize?: number;
  originalName?: string;
  extractor?: string;
  extractStatus?: string; // FULL|PARTIAL|NONE|UNANALYZED
  normalizedText?: string; // 추출 정규화본(텍스트경로) → <sha>.normalized.md 사이드카
  assets?: { name: string; bytes: Buffer; mediaType: string }[]; // 문서 내장 이미지(raw 보존 + 비전 첨부)
}

export interface IngestResult {
  status: "APPLIED" | "SKIPPED_DUP" | "NEEDS_REVIEW";
  sourceId: number;
  jobId?: number;
  commitSha?: string;
  changedPaths?: string[];
  confidence?: number;
  needsHuman?: boolean;
}

// submit_edit_set 도구의 입력 스키마 (docs/06 §2). Phase 1은 op를 create|append로 제한.
const EDIT_SET_SCHEMA: Record<string, unknown> = {
  type: "object",
  properties: {
    edits: {
      type: "array",
      description: "위키에 적용할 파일 편집 목록",
      items: {
        type: "object",
        properties: {
          op: { type: "string", enum: ["create", "append"] },
          path: {
            type: "string",
            description:
              "scope 포함 상대경로. 예: <scope>/entities/결제-게이트웨이.md (kebab-case 파일명, scope는 시스템 지시를 따른다)",
          },
          content: {
            type: "string",
            description: "frontmatter + 본문 + 출처 섹션을 포함한 페이지 전체 markdown",
          },
        },
        required: ["op", "path", "content"],
      },
    },
    log_entry: { type: "string", description: "이 인제스트의 한 줄 이력 요약" },
    confidence: {
      type: "number",
      description: "0~1 자기평가. 새 페이지·모순은 낮게, 링크·오타정정은 높게.",
    },
    needs_human: {
      type: "boolean",
      description: "모순/대체(contradicts/supersedes) 등 사람 검토가 필요하면 true",
    },
  },
  required: ["edits", "log_entry", "confidence"],
};

function buildSystem(brain: string, scope: string): string {
  return [
    brain,
    "",
    "---",
    "당신은 위 '위키 두뇌' 규칙을 따르는 지식 관리자입니다. 업로드된 원본 1건을 읽고,",
    "위키에 적용할 편집셋을 submit_edit_set 도구로 제출하세요. 자유서술이 아니라 도구 호출로만 답합니다.",
    "",
    `★ 모든 편집 경로(path)는 반드시 이 scope 디렉터리 \`${scope}/\` 아래여야 합니다. 다른 scope를 건드리면 거부됩니다.`,
    "",
    "편집 규칙:",
    `- 1 페이지 = 1 개념/개체. 파일명은 kebab-case, scope 하위 디렉터리에 둔다:`,
    `  \`${scope}/entities/\`(사람·조직·시스템·개체) · \`${scope}/concepts/\`(개념·용어) · \`${scope}/topics/\`(주제·종합).`,
    "- 각 페이지는 frontmatter(title, type, scope, links, sources, updated) + 본문 + '## 출처' 섹션.",
    "- 본문에서 다른 페이지를 언급하면 [[제목]] 형태로 상호링크한다.",
    "- 추측 금지: 원본에 없는 사실을 만들지 않는다. 모든 주장은 sources(sha256)로 뒷받침한다.",
    "- ★대량 데이터(표·스프레드시트·긴 목록)는 전체 행을 그대로 옮기지 말 것. 핵심 개념·분류·규칙·대표 예시 위주로 '요약'한다. 위키는 요약 지식이고 원본은 따로 보존돼 사용자가 직접 열람한다. 한 페이지가 비대해지면 개념별로 분할하고, 표는 대표 행 몇 개와 컬럼 의미 설명으로 대체한다.",
    "- 기존 페이지와 같은 주제면: op:create로 같은 path에 '기존+신규를 병합한 전체 내용'을 다시 쓰거나,",
    "  op:append로 새 섹션만 덧붙인다. (기존 내용을 임의로 삭제하지 말 것)",
    `- 변경을 반영해 \`${scope}/index.md\` 전체 내용을 edits에 포함한다(페이지별 한 줄 설명 목차).`,
    "- log_entry는 한 줄 이력(코드가 log.md에 누적하므로 edits에 log.md를 넣지 말 것).",
    "- 모순/대체가 보이면 본문을 덮지 말고 relations에 표기하고 needs_human=true로 사람 검토를 요청한다.",
  ].join("\n");
}

function buildUser(args: {
  scope: string;
  title: string;
  sha: string;
  text: string;
  index: string;
  pages: { path: string; content: string }[];
  nativeAttachment?: boolean; // 이미지/PDF가 본 원본(텍스트는 캡션) — 첨부를 근거로 정리
  embeddedCount?: number; // 추출 텍스트 + 문서 내장 이미지 N장(보조)
}): string {
  const existing =
    args.pages.length === 0
      ? "(아직 위키 페이지가 없습니다 — 첫 인제스트)"
      : args.pages
          .map((p) => `### 기존페이지: ${p.path}\n${p.content}`)
          .join("\n\n");

  return [
    `# 인제스트 대상`,
    `scope: ${args.scope}`,
    `원본 제목: ${args.title}`,
    `원본 sha256: ${args.sha}  (frontmatter sources에 "sha256:${args.sha}" 형태로 표기)`,
    ``,
    `## 현재 목차 (${args.scope}/index.md)`,
    args.index || "(비어 있음)",
    ``,
    `## 현재 위키 페이지들`,
    existing,
    ``,
    args.nativeAttachment
      ? `## 원본 (첨부 자료=이미지/PDF — 첨부 내용을 근거로 정리. 아래는 캡션/지시)`
      : `## 원본 본문 (이 내용만을 근거로 정리)${args.embeddedCount ? ` — 문서 내장 이미지 ${args.embeddedCount}장 첨부(차트·표·도해 내용은 반영, 장식·로고·아이콘은 무시)` : ""}`,
    "```md",
    args.text,
    "```",
  ].join("\n");
}

// ── 로컬(약한 모델)용 단순 인제스트 (PLAN-local-llm-operation §2: task 축소) ──
// 모델은 '콘텐츠만'(제목·요약·태그·본문) 내고, 경로·구조·frontmatter는 코드가 결정한다.
// → 약한 모델의 경로 오생성(`/1`) 제거 + 출력이 작아 빠름. 상호링크·index·needs_human·비전 비활성.
interface SimpleNote { title: string; tags?: string[]; body_markdown: string }

// 필드 최소화(소형 모델의 필드 드리프트 방지) — 제목·태그·본문만. 요약은 본문이 겸한다.
const SIMPLE_SCHEMA: Record<string, unknown> = {
  type: "object",
  properties: {
    title: { type: "string", description: "자료의 핵심 제목(짧게, 한국어)" },
    tags: { type: "array", items: { type: "string" }, description: "키워드 태그 3~6개" },
    body_markdown: { type: "string", description: "원문 핵심을 한국어로 정리한 markdown 본문(소제목·목록 사용 가능)" },
  },
  required: ["title", "body_markdown"],
};

const SIMPLE_SYSTEM =
  "당신은 사내 지식 정리 도우미입니다. 주어진 자료를 읽고 핵심을 한국어로 정리해 JSON으로만 답하세요. " +
  "원문에 있는 내용만 쓰고, 추측하거나 지어내지 마세요.";

function simpleUserText(title: string, text: string): string {
  return ["다음 자료를 읽고 title·tags·body_markdown 을 JSON으로 작성하세요.", "",
    "# 원본 제목", title || "(제목 없음)", "", "# 원본 내용", text].join("\n");
}

function slugify(s: string): string {
  return (s || "").trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "note";
}

// 단순 노트 → 코드가 경로·frontmatter를 정한 EditSet(1페이지). 이후 기존 적용·커밋 파이프라인 공용.
function buildSimpleEditSet(scope: string, note: SimpleNote, sha: string): EditSet {
  const title = (note.title || "제목 없는 노트").replace(/\s+/g, " ").trim();
  const slug = slugify(title);
  const tags = (note.tags ?? []).filter((t) => typeof t === "string" && t.trim()).slice(0, 8);
  const fm = ["---", `title: ${title}`, "type: note", `scope: ${scope}`,
    `tags: ${JSON.stringify(tags)}`, `sources: ${JSON.stringify([`sha256:${sha}`])}`,
    `updated: ${new Date().toISOString().slice(0, 10)}`, "---"].join("\n");
  const content = `${fm}\n\n# ${title}\n\n` +
    `${(note.body_markdown || "").trim()}\n\n## 출처\n- sha256:${sha}\n`;
  return { edits: [{ op: "create", path: `${scope}/topics/${slug}.md`, content }], log_entry: `로컬 인제스트: ${title}`, confidence: 1, needs_human: false };
}

/**
 * 단일 원본 텍스트를 인제스트한다(정규화→sha→dedup→raw 스냅샷→편집셋→적용→커밋).
 * 공급자가 ollama면 단순 경로(콘텐츠만, 코드가 구조 결정), anthropic이면 복잡 편집셋 경로.
 * MVP는 워커를 웹 요청 안에서 인라인 동기로 실행한다(docs/08 Phase 1). Phase 3에서 별도 프로세스로 분리.
 */
export async function ingestText(input: IngestInput): Promise<IngestResult> {
  await assertWikiReady();
  const scope = input.scope ?? "common";
  const type = input.type ?? "MD";
  const text = input.text;
  const sha = createHash("sha256").update(input.rawBytes ?? Buffer.from(text, "utf8")).digest("hex");

  // dedup: 같은 scope에 동일 원본이면 건너뛴다. 단, 이전 인제스트가 '성공(APPLIED)'한
  // 경우만 중복처리하고, 실패/미완료로 남은 자료는 정리 후 재인제스트를 허용한다(재업로드로 재시도).
  const dup = await prisma.source.findUnique({
    where: { teamScope_sha256: { teamScope: scope, sha256: sha } },
    include: { ingestJobs: { where: { status: "APPLIED" }, take: 1 } },
  });
  if (dup) {
    if (dup.ingestJobs.length > 0) return { status: "SKIPPED_DUP", sourceId: dup.id };
    await prisma.ingestJob.deleteMany({ where: { sourceId: dup.id } });
    await prisma.source.delete({ where: { id: dup.id } });
  }

  const now = new Date();
  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const rawExt = input.rawExt ?? "md";
  const rawRel = `raw/${scope}/${yyyy}/${mm}/${sha}.${rawExt}`;
  const stem = rawRel.replace(/\.[^.]+$/, "");
  const normalizedRel = input.normalizedText && input.normalizedText.trim() ? `${stem}.normalized.md` : null;

  const source = await prisma.source.create({
    data: {
      teamScope: scope,
      type,
      sha256: sha,
      title: input.title,
      rawPath: rawRel,
      uploadedBy: input.userId ?? null,
      mimeType: input.mimeType ?? null,
      byteSize: input.byteSize ?? input.rawBytes?.byteLength ?? Buffer.byteLength(text, "utf8"),
      originalName: input.originalName ?? null,
      extractor: input.extractor ?? null,
      extractStatus: input.extractStatus ?? null,
      normalizedPath: normalizedRel,
      provenance: JSON.stringify({ uploadedAt: now.toISOString() }),
    },
  });
  const job = await prisma.ingestJob.create({
    data: { sourceId: source.id, teamScope: scope, status: "RUNNING", model: MODELS.ingest },
  });

  try {
    // LLM 호출(느림)은 git 락 밖에서. 공급자에 따라 단순/복잡 경로 분기.
    let data: EditSet;
    let usage: { inputTokens: number; outputTokens: number };

    if (providerFor("ingest") === "ollama") {
      // 로컬: 단순 스키마(콘텐츠만) → 코드가 경로·구조 결정. 컨텍스트(brain/index/pages) 불필요.
      const r = await callStructured<SimpleNote>({
        model: MODELS.ingest,
        system: SIMPLE_SYSTEM,
        userText: simpleUserText(input.title, text),
        toolName: "submit_note",
        toolDescription: "정리한 노트(JSON).",
        schema: SIMPLE_SCHEMA,
        provider: "ollama",
        maxTokens: Number(process.env.INGEST_MAX_TOKENS || 4096),
      });
      usage = r.usage;
      data = buildSimpleEditSet(scope, r.data, sha);
    } else {
      // Claude: 두뇌 규칙 + 목차 + 기존 페이지 컨텍스트 → 복잡 편집셋(상호링크·index 유지).
      const [brain, index, pages] = await Promise.all([loadBrain(), loadIndex(scope), loadPages(scope)]);
      const assetImages = (input.assets ?? []).map((a) => ({ mediaType: a.mediaType, dataBase64: a.bytes.toString("base64") }));
      const allImages = [...(input.images ?? []), ...assetImages];
      const r = await callStructured<EditSet>({
        model: MODELS.ingest,
        system: buildSystem(brain, scope),
        userText: buildUser({
          scope, title: input.title, sha, text, index, pages,
          nativeAttachment: ((input.images?.length ?? 0) + (input.documents?.length ?? 0) > 0) && !input.normalizedText,
          embeddedCount: input.assets?.length ?? 0,
        }),
        toolName: "submit_edit_set",
        toolDescription: "위키에 적용할 편집셋(JSON). 워커가 파일에 적용하고 git 커밋한다.",
        schema: EDIT_SET_SCHEMA,
        provider: providerFor("ingest"),
        maxTokens: Number(process.env.INGEST_MAX_TOKENS || 20000), // 큰 자료의 편집셋 잘림 방지
        images: allImages.length ? allImages : undefined,
        documents: input.documents,
      });
      usage = r.usage;
      data = r.data;
      if (!Array.isArray(data.edits)) throw new Error("LLM이 유효한 편집셋(edits 배열)을 반환하지 않았습니다.");
    }

    // 적용 + 커밋은 단일 라이터 임계구역에서(raw 스냅샷 기록 포함).
    // 거버넌스 게이트(REQ-WIKI-007/REQ-REVIEW-004, docs/12): 모순/대체(needs_human) 또는
    // 저신뢰(confidence < INGEST_T_REVIEW)면 편집셋 미적용·검토 큐로. 원본은 보존, 승인 시 적용.
    const T_REVIEW = Number(process.env.INGEST_T_REVIEW || 0.5);
    const apply = !data.needs_human && (data.confidence ?? 1) >= T_REVIEW;
    const { commitSha, changed } = await withWikiWriteLock(async () => {
      const rawAbs = wikiAbsPath(rawRel);
      await fs.mkdir(path.dirname(rawAbs), { recursive: true });
      await fs.writeFile(rawAbs, input.rawBytes ?? text);

      const extra: string[] = [];
      // 문서 내장 이미지 자산 보존 (raw/<sha>.assets/NN.ext)
      if (input.assets?.length) {
        const assetsDir = wikiAbsPath(`${stem}.assets`);
        await fs.mkdir(assetsDir, { recursive: true });
        for (let i = 0; i < input.assets.length; i++) {
          const a = input.assets[i];
          const aext = a.mediaType.split("/")[1] || "png";
          const arel = `${stem}.assets/${String(i + 1).padStart(2, "0")}.${aext}`;
          await fs.writeFile(wikiAbsPath(arel), a.bytes);
          extra.push(arel);
        }
      }
      // 정규화 추출본 사이드카 (<sha>.normalized.md)
      if (normalizedRel) {
        await fs.writeFile(wikiAbsPath(normalizedRel), input.normalizedText!, "utf8");
        extra.push(normalizedRel);
      }

      const changed = apply ? await applyEditSet(scope, data) : [];
      const commitSha = await commitAll(
        apply ? `ingest(${scope}): ${input.title}` : `ingest-pending(${scope}): ${input.title} [검토대기]`,
        {
          sourceSha256: sha,
          sourceType: type,
          team: scope,
          confidence: data.confidence,
          gate: apply ? "AUTO_APPLIED" : "HUMAN_REVIEW",
          model: MODELS.ingest,
        },
      );
      return { commitSha, changed: [rawRel, ...extra, ...changed] };
    });

    await prisma.ingestJob.update({
      where: { id: job.id },
      data: {
        status: apply ? "APPLIED" : "NEEDS_REVIEW",
        editSet: JSON.stringify(data),
        confidence: data.confidence,
        gate: apply ? "AUTO_APPLIED" : "HUMAN_REVIEW",
        commitSha,
      },
    });

    await recordUsage({ userId: input.userId, scope, kind: "ingest", model: MODELS.ingest, inputTokens: usage.inputTokens, outputTokens: usage.outputTokens });

    return {
      status: apply ? "APPLIED" : "NEEDS_REVIEW",
      sourceId: source.id,
      jobId: job.id,
      commitSha,
      changedPaths: changed,
      confidence: data.confidence,
      needsHuman: data.needs_human,
    };
  } catch (err) {
    console.error(`[ingest] FAILED source=${source.id} scope=${scope} title="${input.title}": ${String(err)}`);
    // 실패한 자료는 '실패' 상태로 남겨 사용자에게 보이게 한다(흔적 없이 사라지지 않도록).
    // 같은 파일 재업로드 시에는 위 dedup 분기가 이 실패본을 정리하고 재인제스트한다.
    await prisma.ingestJob.update({
      where: { id: job.id },
      data: { status: "FAILED", attempts: { increment: 1 }, error: String(err) },
    }).catch(() => {});
    throw err;
  }
}

/**
 * 분석 불가(미지원·추출실패) 파일도 원본은 보존한다(REQ-MAT-010). LLM 호출 없이
 * raw 보존 + Source(extractStatus=UNANALYZED) 생성 + 단일 라이터 커밋만 수행.
 */
export async function storeRawOnly(input: {
  scope: string;
  title: string;
  rawBytes: Buffer;
  rawExt: string;
  userId?: number | null;
  mimeType?: string;
  byteSize?: number;
  originalName?: string;
}): Promise<{ status: "UNANALYZED" | "SKIPPED_DUP"; sourceId: number }> {
  await assertWikiReady();
  const sha = createHash("sha256").update(input.rawBytes).digest("hex");
  const dup = await prisma.source.findUnique({
    where: { teamScope_sha256: { teamScope: input.scope, sha256: sha } },
  });
  if (dup) return { status: "SKIPPED_DUP", sourceId: dup.id };

  const now = new Date();
  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const rawRel = `raw/${input.scope}/${yyyy}/${mm}/${sha}.${input.rawExt}`;

  const source = await prisma.source.create({
    data: {
      teamScope: input.scope,
      type: input.rawExt.toUpperCase(),
      sha256: sha,
      title: input.title,
      rawPath: rawRel,
      uploadedBy: input.userId ?? null,
      mimeType: input.mimeType ?? null,
      byteSize: input.byteSize ?? input.rawBytes.byteLength,
      originalName: input.originalName ?? null,
      extractor: "none",
      extractStatus: "UNANALYZED",
      provenance: JSON.stringify({ uploadedAt: now.toISOString(), unanalyzed: true }),
    },
  });

  try {
    await withWikiWriteLock(async () => {
      const abs = wikiAbsPath(rawRel);
      await fs.mkdir(path.dirname(abs), { recursive: true });
      await fs.writeFile(abs, input.rawBytes);
      return commitAll(`store(${input.scope}): ${input.title} [미분석]`, {
        team: input.scope,
        sourceType: input.rawExt.toUpperCase(),
        sourceSha256: sha,
        gate: "UNANALYZED",
      });
    });
  } catch (err) {
    // raw 보존 실패 시 Source 행을 롤백(고아행·dedup 영구차단 방지, REQ-MAT-010 유지)
    await prisma.source.delete({ where: { id: source.id } }).catch(() => {});
    throw err;
  }

  return { status: "UNANALYZED", sourceId: source.id };
}

