import { providerFor } from "./anthropic";
import { SUPPORTED_EXTS } from "./extract";
import { CONVERT_ONLY_EXTS, libreOfficeAvailable } from "./convert";

// 업로드 정책 단일 소스(PLAN-free-paid-upload-gating). 클라/서버가 같은 값을 보게
// 서버가 계산해 API로 클라에 내려준다(클라는 무거운 server-only deps를 import하지 않음).
// 게이팅 기준 = 인제스트 공급자: ollama(무료·약한 모델)면 텍스트만, anthropic이면 전체 포맷.

export interface UploadPolicy {
  provider: string;
  textOnly: boolean;
  exts: string[]; // 허용 확장자(소문자, 점 없음)
  accept: string; // <input accept>
  note: string; // UI 안내 문구
}

const TEXT_EXTS = ["txt", "md", "markdown"];

export function currentUploadPolicy(): UploadPolicy {
  const provider = providerFor("ingest");
  if (provider === "ollama") {
    return {
      provider,
      textOnly: true,
      exts: TEXT_EXTS,
      accept: ".txt,.md,.markdown,text/plain,text/markdown",
      note: "무료 로컬 모델은 텍스트(.txt·.md)만 받습니다. PDF·워드·엑셀·한글·이미지는 ChatGPT 같은 AI로 '핵심만 요약한 텍스트'로 바꿔서 올려주세요(요약할수록 품질·속도가 좋아집니다).",
    };
  }
  const exts = [...SUPPORTED_EXTS, ...(libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [])];
  return {
    provider,
    textOnly: false,
    exts,
    accept: exts.map((e) => `.${e}`).join(","),
    note: "PDF·오피스·한글·이미지까지 그대로 올리면 AI가 분석합니다.",
  };
}

export function extOf(filename: string): string {
  return filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";
}

export function isAllowedUpload(filename: string, pol: UploadPolicy = currentUploadPolicy()): boolean {
  return pol.exts.includes(extOf(filename));
}

