import Anthropic from "@anthropic-ai/sdk";

// 모듈 로드만으로 죽지 않게, 키 미설정은 경고만. 실제 호출 시점에 SDK가 에러를 던진다.
if (!process.env.ANTHROPIC_API_KEY) {
  console.warn(
    "[anthropic] ANTHROPIC_API_KEY 미설정 — 인제스트/질의 호출 시 실패합니다 (.env 확인).",
  );
}

export const anthropic = new Anthropic({ apiKey: [REDACTED-SECRET] });

export type LlmPurpose = "ingest" | "query";

// LLM 공급자: 'anthropic'(API 키·크레딧) 또는 'ollama'(로컬 무료·데이터 PC 밖으로 안 나감).
// 용도별(INGEST_PROVIDER/QUERY_PROVIDER) > 전역(LLM_PROVIDER) > 기본 anthropic 순으로 적용.
// → 나중에 회사가 Claude API를 결제하면 .env만 바꿔 "질의는 Claude·인제스트는 로컬"처럼 섞을 수 있다.
export function providerFor(purpose: LlmPurpose): string {
  const specific = purpose === "ingest" ? process.env.INGEST_PROVIDER : process.env.QUERY_PROVIDER;
  return (specific || process.env.LLM_PROVIDER || "anthropic").toLowerCase();
}
export function llmProvider(): string {
  return (process.env.LLM_PROVIDER || "anthropic").toLowerCase();
}

// docs/03 §3: 인제스트=Sonnet(비용), 질의=Opus(정확도). 용도별 모델은 명시값 우선, 없으면 공급자 기본.
// 로컬(ollama)이면 ollama 모델명(예: qwen2.5:3b)으로 폴백.
export function modelFor(purpose: LlmPurpose): string {
  const explicit = purpose === "ingest" ? process.env.INGEST_MODEL : process.env.QUERY_MODEL;
  if (explicit) return explicit;
  if (providerFor(purpose) === "ollama") return process.env.OLLAMA_DEFAULT_MODEL || "qwen2.5:3b";
  return purpose === "ingest" ? "claude-sonnet-4-6" : "claude-opus-4-8";
}

// 기존 호출부 호환(MODELS.ingest/query). 게터라 호출 시점의 용도·공급자를 반영한다.
export const MODELS = {
  get ingest() { return modelFor("ingest"); },
  get query() { return modelFor("query"); },
};

export interface Usage {
  inputTokens: number;
  outputTokens: number;
}

/**
 * 단일 도구를 강제(tool_choice)해 구조화된 JSON 출력을 안정적으로 받는다.
 * LLM은 위키 본문/편집셋을 자유 텍스트가 아니라 검증된 객체로 반환한다(docs/03 §3).
 */
export async function callStructured<T>(opts: {
  model: string;
  system: string;
  userText: string;
  toolName: string;
  toolDescription: string;
  schema: Record<string, unknown>;
  maxTokens?: number;
  images?: { mediaType: string; dataBase64: string }[]; // 비전(이미지) 입력
  documents?: { mediaType: string; dataBase64: string }[]; // 문서(PDF) 입력
  provider?: string; // 호출별 공급자 오버라이드(용도별 선택). 없으면 전역 LLM_PROVIDER.
}): Promise<{ data: T; usage: Usage }> {
  // 로컬 공급자면 Ollama 어댑터로 위임(동일 인터페이스). 외부 전송 없음.
  if ((opts.provider ?? llmProvider()) === "ollama") {
    const { ollamaStructured } = await import("./ollama");
    return ollamaStructured<T>(opts);
  }

  const hasAttachment = (opts.images?.length ?? 0) + (opts.documents?.length ?? 0) > 0;
  const content: Anthropic.MessageParam["content"] = hasAttachment
    ? [
        ...(opts.images ?? []).map((im) => ({
          type: "image" as const,
          source: { type: "base64" as const, media_type: im.mediaType as "image/png", data: im.dataBase64 },
        })),
        ...(opts.documents ?? []).map((doc) => ({
          type: "document" as const,
          source: { type: "base64" as const, media_type: doc.mediaType as "application/pdf", data: doc.dataBase64 },
        })),
        { type: "text" as const, text: opts.userText },
      ]
    : opts.userText;
  const res = await anthropic.messages.create({
    model: opts.model,
    max_tokens: opts.maxTokens ?? 8192,
    system: opts.system,
    messages: [{ role: "user", content }],
    tools: [
      {
        name: opts.toolName,
        description: opts.toolDescription,
        input_schema: opts.schema as Anthropic.Tool.InputSchema,
      },
    ],
    tool_choice: { type: "tool", name: opts.toolName },
  });

  // 출력이 max_tokens에서 잘리면 tool_use input JSON이 불완전(edits 누락)해 적용 단계에서
  // 'edits is not iterable'로 죽는다. 잘림을 명확한 에러로 변환해 부분 적용을 막는다.
  if (res.stop_reason === "max_tokens") {
    throw new Error("LLM 출력이 최대 길이(max_tokens)에 도달해 편집셋이 잘렸습니다. 자료가 너무 큽니다 — 더 작게 나눠 올려주세요.");
  }
  const block = res.content.find((b) => b.type === "tool_use");
  if (!block || block.type !== "tool_use") {
    throw new Error("LLM이 구조화 출력(tool_use)을 반환하지 않았습니다.");
  }
  return {
    data: block.input as T,
    usage: {
      inputTokens: res.usage.input_tokens,
      outputTokens: res.usage.output_tokens,
    },
  };
}

